using System;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Windows.Forms;namespace AshkanSocial.UI.Controls{public sealed class BackgroundSurface:Panel{Image image;public int OverlayAlpha{get;set;}=145;public BackgroundSurface(){DoubleBuffered=true;Dock=DockStyle.Fill;try{var p=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Assets","social-background.png");if(File.Exists(p))image=Image.FromFile(p);}catch{}}protected override void OnPaintBackground(PaintEventArgs e){if(image==null){base.OnPaintBackground(e);return;}e.Graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;e.Graphics.DrawImage(image,ClientRectangle);using(var b=new SolidBrush(Color.FromArgb(OverlayAlpha,10,24,42)))e.Graphics.FillRectangle(b,ClientRectangle);}protected override void Dispose(bool disposing){if(disposing&&image!=null)image.Dispose();base.Dispose(disposing);}}}